import{_ as n,o as r,c as l,ah as s}from"./chunks/framework.CfQBrslM.js";const A="/projects/AiArm/en/latest/assets/image2.BP29WQlN.png",c="/projects/AiArm/en/latest/assets/image3.w5Koh4FE.png",g="/projects/AiArm/en/latest/assets/image4.Dt-erNuP.png",d="data:image/png;base64,",m="data:image/png;base64,",h="data:image/png;base64,",p="data:image/png;base64,",u="/projects/AiArm/en/latest/assets/image7.BANZOG_c.png",y="data:image/png;base64,",f="/projects/AiArm/en/latest/assets/image11.BpmZJNVZ.png",w="/projects/AiArm/en/latest/assets/image12.Bsv4muip.png",k="/projects/AiArm/en/latest/assets/image13.DFroc9p3.png",R="/projects/AiArm/en/latest/assets/image14.D0d4XAVK.png",I="/projects/AiArm/en/latest/assets/image15.Ct4wbWdQ.png",C="/projects/AiArm/en/latest/assets/image16.By6sT-oR.png",b="/projects/AiArm/en/latest/assets/image2.BP29WQlN.png",S="/projects/AiArm/en/latest/assets/image3.BUca0ii6.png",a="/projects/AiArm/en/latest/assets/image4.C5mGALcn.png",V="data:image/png;base64,",z="data:image/png;base64,",O="data:image/png;base64,",B="data:image/png;base64,",J="/projects/AiArm/en/latest/assets/image7.BANZOG_c.png",K="data:image/png;base64,",P="/projects/AiArm/en/latest/assets/image11.GLkhKGdC.png",q="/projects/AiArm/en/latest/assets/image12.CeTfKR9n.png",e="data:image/png;base64,",t="data:image/png;base64,",o="data:image/png;base64,",v="/projects/AiArm/en/latest/assets/image2.BP29WQlN.png",U="/projects/AiArm/en/latest/assets/image6.Bby9dq52.png",T="/projects/AiArm/en/latest/assets/image7.CGEGeljU.png",x="data:image/png;base64,",H="data:image/png;base64,",E="data:image/png;base64,",X="data:image/png;base64,",L="/projects/AiArm/en/latest/assets/image7.BANZOG_c.png",M="data:image/png;base64,",Z="/projects/AiArm/en/latest/assets/image14.DlQnMiyn.png",Q="/projects/AiArm/en/latest/assets/image15._BaFAFtW.png",W="/projects/AiArm/en/latest/assets/image16.DOvxO2SA.png",j="/projects/AiArm/en/latest/assets/image17.0F2igXCx.png",D="/projects/AiArm/en/latest/assets/image18.BBm6cS8C.png",oe=JSON.parse('{"title":"6. Vision Recognition and Applications","description":"","frontmatter":{},"headers":[],"relativePath":"docs/6.Vision Recognition and Applications.md","filePath":"docs/6.Vision Recognition and Applications.md"}'),N={name:"docs/6.Vision Recognition and Applications.md"};function G(Y,i,F,_,$,ee){return r(),l("div",null,[...i[0]||(i[0]=[s('<h1 id="_6-vision-recognition-and-applications" tabindex="-1">6. Vision Recognition and Applications <a class="header-anchor" href="#_6-vision-recognition-and-applications" aria-label="Permalink to &quot;6. Vision Recognition and Applications&quot;">​</a></h1><h2 id="_6-1-color-recognition-and-sorting" tabindex="-1">6.1 Color Recognition and Sorting <a class="header-anchor" href="#_6-1-color-recognition-and-sorting" aria-label="Permalink to &quot;6.1 Color Recognition and Sorting&quot;">​</a></h2><ol><li>When WonderCam vision module detects red, green and blue objects, RGB lights on the main controller will illuminate in the corresponding color. Then, the robot arm will sort the colored blocks based on color to corresponding area.</li></ol><h3 id="_6-1-1-preparation" tabindex="-1">6.1.1 Preparation <a class="header-anchor" href="#_6-1-1-preparation" aria-label="Permalink to &quot;6.1.1 Preparation&quot;">​</a></h3><ol><li><p>Let WonderCam vision module learn red, green and blue. For detailed instruction, please refer to the files locating in the folder “<strong>1. WonderCam Vision Module Usage</strong>”.</p></li><li><p>Connect WonderCam vision module to port 9 of CoreX controller.</p></li><li><p>Install WonderCode programming software according to the instructions provided in “<strong>3. Scratch Programming</strong>”.</p></li></ol><h3 id="_6-1-2-program-logic" tabindex="-1">6.1.2 <strong>Program Logic</strong> <a class="header-anchor" href="#_6-1-2-program-logic" aria-label="Permalink to &quot;6.1.2 **Program Logic**&quot;">​</a></h3><ol><li><p>To start, the robot arm will initiate the initialization process, which involves running a specific action group to adjust its position for efficient color recognition. Following this, any modules not relevant to this game will be disabled.</p></li><li><p>Once the initialization process is complete, the WonderCam module will begin detecting colored blocks.</p></li><li><p>When the WonderCam module recognizes a colored block, the LED on the CoreX controller will illuminate in the corresponding color. For example, if the WonderCam recognizes a red block, the LED on the CoreX controller will light up in red. After the recognition step is finished, AiArm will invoke the appropriate action group to sort the block.</p></li><li><p>For a more detailed implementation of this game, please refer to the <strong>5. Program Analysis</strong> section.</p></li></ol><h3 id="_6-1-3-download-program" tabindex="-1">6.1.3 Download Program <a class="header-anchor" href="#_6-1-3-download-program" aria-label="Permalink to &quot;6.1.3 Download Program&quot;">​</a></h3><ol><li>Open WonderCode software.</li></ol><img loading="lazy" height="107" width="98" src="'+A+'" class="common_img" style="width:300px;"><ol start="2"><li>Directly drag the program file saved in the folder “<strong>Programs</strong>” to WonderCode interface.</li></ol><img loading="lazy" height="163" width="627" src="'+c+'" class="common_img" style="width:800px;"><img loading="lazy" height="606" width="928" src="'+g+'" class="common_img" style="width:800px;"><ol start="3"><li>Click-on <img loading="lazy" height="48" width="154" src="'+d+'" class="inline-icon"> and select the corresponding COM port, for example COM4. Please note that COM port options may differ from each computer.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>please do not select COM1, as it used for communication port in general.</strong></p></div><img loading="lazy" height="113" width="178" src="'+m+'" class="common_img" style="width:300px;"><img loading="lazy" height="68" width="189" src="'+h+'" class="common_img" style="width:300px;"><ol start="4"><li>Click-on <img loading="lazy" height="45" width="46" src="'+p+'" class="inline-icon"> icon to upload the complete program.</li></ol><img loading="lazy" height="133" width="564" src="'+u+'" class="common_img" style="width:800px;"><ol start="5"><li>The upload may take some times, and please be patient!</li></ol><img loading="lazy" height="34" width="121" src="'+y+'" class="common_img" style="width:800px;"><h3 id="_6-1-4-program-outcome" tabindex="-1">6.1.4 Program Outcome <a class="header-anchor" href="#_6-1-4-program-outcome" aria-label="Permalink to &quot;6.1.4 Program Outcome&quot;">​</a></h3><ol><li>After successfully downloading the programs, follow the sequence of turning on the switch on the robot arm and the main controller. As a result, the WonderCam vision module will seamlessly transition into <strong>Color Recognition</strong> mode.</li><li>Upon identifying the relevant colored block, the buzzer on the CoreX controller will emit a brief beep, accompanied by the RGB light on the main controller illuminating in the corresponding color.</li><li>Subsequently, the robot arm will initiate the sorting process within the recognition zone and position the block on the right side of the robot arm.</li></ol><h3 id="_6-1-5-program-analysis" tabindex="-1">6.1.5 Program Analysis <a class="header-anchor" href="#_6-1-5-program-analysis" aria-label="Permalink to &quot;6.1.5 Program Analysis&quot;">​</a></h3><ol><li><strong>Initial Settings</strong></li></ol><p>​ (1) To begin, WonderCam vision module will switch to color recognition. Next, an action group labeled as <strong>0</strong> will be invoked to position the robot arm in a downward attitude, facilitating efficient recognition.</p><p>​ (2) In addition, to avoid any potential interference with color recognition, the ultrasonic module will be turned off.</p><p>​ (3) A variable named <strong>target area</strong> will be established, with an initial value of 0. The detected area value of the color block will be assigned to this variable, allowing for further processing or analysis.</p><img loading="lazy" height="272" width="815" src="'+f+'" class="common_img" style="width:800px;"><ol start="2"><li><strong>Color Recognition</strong></li></ol><p>​ (1) AiArm utilizes WonderCam vision module to achieve color recognition. A repetitive loop statement will be used to enable the vision module to recognize repeatedly. For example, when recognizing a red block, WonderCam vision module will perform recognition again to ensure the accuracy of the recognition result.</p><img loading="lazy" height="182" width="881" src="'+w+'" class="common_img" style="width:800px;"><p>​ (2) If the WonderCam vision module successfully detects a red block, it will set two variables, namely <strong>height</strong> and <strong>width,</strong> to store the dimensions of the block image obtained from the module. Once these values are obtained, the area of the block image can be calculated. Subsequently, the following condition can be used to determine if the block area meets the specified threshold, confirming the identified object as the red block.</p><img loading="lazy" height="60" width="799" src="'+k+'" class="common_img" style="width:800px;"><ol start="3"><li><strong>Recognition Feedback</strong></li></ol><p>​ (1) Configure recognition feedback based on color.</p><p>​ (2) If WonderCam module detects the color of the block is ID1 (red), set the color of LED light to red. At this time, RGB light on CoreX controller will illuminate in red, and the buzzer will make a short beeping. If no color is recognized, CoreX controller’s light will go off.</p><img loading="lazy" height="118" width="724" src="'+R+'" class="common_img" style="width:800px;"><img loading="lazy" height="65" width="536" src="'+I+'" class="common_img" style="width:800px;"><ol start="4"><li><strong>Robot Arm Sorting</strong></li></ol><p>​ (1) When WonderCam vision module recognizes the colored block, it will call specific action group to start sorting the block based on color. To learn more about action group editing, please refer to this chapter ““<strong>2. AiArm Control</strong>”.</p><p>​ (2) Action group <strong>“0”</strong> will be called to set the initial position of the robot arm facilitating color recognition.</p><p>​ (3) When recognizing the colored block, AiArm will execute action group 1 once to pick up the colored block. After a while, it will perform action group 2 to sort and place the block to corresponding area.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>action groups 0-30 are encrypted and serve as the mandatory action groups for robot games. If you intend to create a new action group, kindly ensure that you begin saving it from No. 31 onwards.</strong></p></div><img loading="lazy" height="173" width="599" src="'+C+'" class="common_img" style="width:800px;"><h2 id="_6-2-tag-recognition-and-sorting" tabindex="-1">6.2 Tag Recognition and Sorting <a class="header-anchor" href="#_6-2-tag-recognition-and-sorting" aria-label="Permalink to &quot;6.2 Tag Recognition and Sorting&quot;">​</a></h2><ol><li>When WonderCam vision module detects tag blocks, buzzer will emit a short beeping. Then, the robot arm will sort the tag blocks to its right side.</li></ol><h3 id="_6-2-1-preparation" tabindex="-1">6.2.1 Preparation <a class="header-anchor" href="#_6-2-1-preparation" aria-label="Permalink to &quot;6.2.1 Preparation&quot;">​</a></h3><ol><li><p>Connect WonderCam vision module to port 9 of CoreX controller.</p></li><li><p>Install WonderCode programming software according to the instructions provided in “<strong>3. Scratch Programming</strong>”.</p></li></ol><h3 id="_6-2-2-program-logic" tabindex="-1">6.2.2 <strong>Program Logic</strong> <a class="header-anchor" href="#_6-2-2-program-logic" aria-label="Permalink to &quot;6.2.2 **Program Logic**&quot;">​</a></h3><ol><li><p>To start, the robot arm will initiate the initialization process, which involves running a specific action group to adjust its position for efficient tag recognition. Following this, any modules not relevant to this game will be disabled.</p></li><li><p>Once the initialization process is complete, the WonderCam module will actively detect tags. When the WonderCam vision module recognizes a tag, the buzzer on the main controller will emit a short beep. Subsequently, the robot arm will execute a designated action group to sort the tags.</p></li><li><p>For a more comprehensive understanding of the game&#39;s implementation, please refer to the <strong>5. Program Analysis</strong> section.</p></li></ol><h3 id="_6-2-3-download-program" tabindex="-1">6.2.3 Download Program <a class="header-anchor" href="#_6-2-3-download-program" aria-label="Permalink to &quot;6.2.3 Download Program&quot;">​</a></h3><ol><li>Open WonderCode software.</li></ol><img loading="lazy" height="107" width="98" src="'+b+'" class="common_img" style="width:300px;"><ol start="2"><li>Directly drag the corresponding program file saved in the folder “<strong>Programs</strong>” to WonderCode interface.</li></ol><img loading="lazy" height="173" width="615" src="'+S+'" class="common_img" style="width:800px;"><img loading="lazy" height="803" width="1013" src="'+a+'" class="common_img" style="width:800px;"><ol start="3"><li>Click-on <img loading="lazy" height="48" width="154" src="'+V+'" class="inline-icon"> and select the corresponding COM port, for example COM4. Please note that COM port options may differ from each computer.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>please do not select COM1, as it used for communication port in general.</strong></p></div><img loading="lazy" height="113" width="178" src="'+z+'" class="common_img" style="width:300px;"><img loading="lazy" height="68" width="189" src="'+O+'" class="common_img" style="width:300px;"><ol start="4"><li>Click-on <img loading="lazy" height="45" width="46" src="'+B+'" class="inline-icon"> icon to upload the complete program.</li></ol><img loading="lazy" height="133" width="564" src="'+J+'" class="common_img" style="width:800px;"><ol start="5"><li>The upload may take some times, and please be patient!</li></ol><img loading="lazy" height="34" width="121" src="'+K+'" class="common_img" style="width:300px;"><h3 id="_6-2-4-program-outcome" tabindex="-1">6.2.4 Program Outcome <a class="header-anchor" href="#_6-2-4-program-outcome" aria-label="Permalink to &quot;6.2.4 Program Outcome&quot;">​</a></h3><ol><li>After successfully downloading the programs, follow the sequence of turning on the switch on the robot arm and the main controller. As a result, the WonderCam vision module will seamlessly transition into <strong>Tag Recognition</strong> mode. Upon identifying the tag, the buzzer on the CoreX controller will emit a brief beep.</li><li>Subsequently, the robot arm will sort and place the tag blocks to corresponding zone according to their ID. Tag 1 will be placed to the area where red block is placed. Tag 2 will be placed to the area where green block is placed. Tag 3 will be placed to the area where blue block is positioned.</li></ol><h3 id="_6-2-5-program-analysis" tabindex="-1">6.2.5 Program Analysis <a class="header-anchor" href="#_6-2-5-program-analysis" aria-label="Permalink to &quot;6.2.5 Program Analysis&quot;">​</a></h3><ol><li><strong>Initial Settings</strong></li></ol><p>​ (1) To begin, WonderCam vision module will switch to tag recognition. Next, an action group labeled as <strong>0</strong> will be invoked to position the robot arm in a downward attitude, facilitating efficient recognition.</p><p>​ (2) In addition, to avoid any potential interference with tag recognition, the ultrasonic module will be turned off.</p><img loading="lazy" height="803" width="1013" src="'+a+'" class="common_img" style="width:800px;"><ol start="2"><li><strong>Tag Recognition</strong></li></ol><p>​ (1) A repetitive loop statement will be used to enable the vision module to recognize repeatedly. For example, when recognizing a tag 1, WonderCam vision module will perform recognition again to ensure the accuracy of the recognition result.</p><img loading="lazy" height="207" width="661" src="'+P+'" class="common_img" style="width:800px;"><ol start="3"><li><strong>Recognition Feedback and Sorting</strong></li></ol><p>​ (1) Configure the feedback of the robot arm based on the recognized tag ID. For instance, when the WonderCam module identifies tag 1, the buzzer emits a short beep, prompting the robot arm to activate action group 1 for object gripping. Once the object is successfully grasped, action group 2 is executed to position the object in the corresponding area.</p><img loading="lazy" height="255" width="930" src="'+q+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ol><li><p><strong>To learn more about action group editing, please refer to this chapter “2. AiArm Control”.</strong></p></li><li><p><strong>Action groups 0-30 are encrypted and serve as the mandatory action groups for robot games. If you intend to create a new action group, kindly ensure that you begin saving it from No. 31 onwards.</strong></p></li></ol></div><h2 id="_6-3-mask-identification" tabindex="-1">6.3 Mask Identification <a class="header-anchor" href="#_6-3-mask-identification" aria-label="Permalink to &quot;6.3 Mask Identification&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Prior to initiating this game, please ensure that the mask recognition model has been successfully uploaded to the WonderCam module. For detailed instructions, kindly refer to the Appendix / WoonderCam Firmware and Firmware installation Tool section.</strong></p></div><ol><li>The WonderCam is designed to identify faces within its field of view. When a face wearing a mask is detected, the dot matrix module will illuminate a smiling face. On the other hand, if a face without a mask is recognized, the dot matrix module will display an <strong>X</strong> symbol.</li></ol><h3 id="_6-3-1-preparation" tabindex="-1">6.3.1 Preparation <a class="header-anchor" href="#_6-3-1-preparation" aria-label="Permalink to &quot;6.3.1 Preparation&quot;">​</a></h3><ol><li><p>Connect WonderCam vision module to port 9 of CoreX controller.</p></li><li><p>Install WonderCode programming software according to the instructions provided in “<strong>3. Scratch Programming</strong>”.</p></li></ol><h3 id="_6-3-2-program-logic" tabindex="-1">6.3.2 <strong>Program Logic</strong> <a class="header-anchor" href="#_6-3-2-program-logic" aria-label="Permalink to &quot;6.3.2 **Program Logic**&quot;">​</a></h3><ol><li><p>To begin with, the robot arm undergoes initialization, which includes configuring the module interface and dot matrix module while setting the initial state. Action group No. 9 is called to position the robot arm in a head-up state, facilitating face recognition.</p></li><li><p>Mask recognition is achieved using pre-trained mask models. Users need not train the models themselves; they can simply follow the instructions provided in <strong>5. WonderCam Vision Module Usage/1. WonderCam Vision Module Usage</strong> for model burning and usage tutorials.</p></li><li><p>During mask identification, the WonderCam vision module utilizes image classification to determine if individuals are wearing masks. If no face is detected, the dot matrix module will display a specific pattern <img loading="lazy" height="24" width="40" src="'+e+'" class="inline-icon">. When a face with a mask is detected, the dot matrix module will exhibit a different pattern <img loading="lazy" height="19" width="39" src="'+t+'" class="inline-icon">, while a separate pattern will be displayed if a face without a mask is detected <img loading="lazy" height="21" width="41" src="'+o+'" class="inline-icon">.</p></li><li><p>For detailed information on the specific implementation of this gameplay, please refer to the <strong>5. Program Analysis</strong> section of this document.</p></li></ol><h3 id="_6-3-3-download-program" tabindex="-1">6.3.3 Download Program <a class="header-anchor" href="#_6-3-3-download-program" aria-label="Permalink to &quot;6.3.3 Download Program&quot;">​</a></h3><ol><li>Open WonderCode software.</li></ol><img loading="lazy" height="107" width="98" src="'+v+'" class="common_img" style="width:300px;"><ol start="2"><li>Directly drag the corresponding program file saved in the folder “<strong>Programs</strong>” to WonderCode interface.</li></ol><img loading="lazy" height="175" width="638" src="'+U+'" class="common_img" style="width:800px;"><img loading="lazy" height="751" width="874" src="'+T+'" class="common_img" style="width:800px;"><ol start="3"><li>Click-on <img loading="lazy" height="48" width="154" src="'+x+'" class="inline-icon"> and select the corresponding COM port, for example COM4. Please note that COM port options may differ from each computer.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>please do not select COM1, as it used for communication port in general.</strong></p></div><img loading="lazy" height="113" width="178" src="'+H+'" class="common_img" style="width:300px;"><img loading="lazy" height="68" width="189" src="'+E+'" class="common_img" style="width:300px;"><ol start="4"><li>Click-on <img loading="lazy" height="45" width="46" src="'+X+'" class="inline-icon"> icon to upload the complete program.</li></ol><img loading="lazy" height="133" width="564" src="'+L+'" class="common_img" style="width:800px;"><ol start="5"><li>The upload may take some times, and please be patient!</li></ol><img loading="lazy" height="34" width="121" src="'+M+'" class="common_img" style="width:800px;"><h3 id="_6-3-4-program-outcome" tabindex="-1">6.3.4 Program Outcome <a class="header-anchor" href="#_6-3-4-program-outcome" aria-label="Permalink to &quot;6.3.4 Program Outcome&quot;">​</a></h3><ol><li><p>Once the program download is complete, follow these steps:</p></li><li><p>First, turn on the switch of the robotic arm. Then, turn on the switch of the main controller. The WonderCam vision module will automatically switch to the <strong>image classification</strong> function. Following by the robotic arm will be set to a head-up position.</p></li><li><p>Next, the dot matrix module will illuminate with a specific pattern <img loading="lazy" height="24" width="40" src="'+e+'" class="inline-icon">. During the mask recognition process: If a face wearing a mask is detected, the dot matrix module will display the corresponding pattern<img loading="lazy" height="19" width="39" src="'+t+'" class="inline-icon">. If a face without a mask is detected, the dot matrix module will display a different pattern<img loading="lazy" height="21" width="41" src="'+o+'" class="inline-icon">.</p></li><li><p>Please ensure that the switches are turned on in the specified sequence to ensure proper functionality.</p></li></ol><h3 id="_6-3-5-program-analysis" tabindex="-1">6.3.5 Program Analysis <a class="header-anchor" href="#_6-3-5-program-analysis" aria-label="Permalink to &quot;6.3.5 Program Analysis&quot;">​</a></h3><ol><li><strong>Initial Settings</strong></li></ol><p>​ (1) To begin, designate interface No. 9 as the interface for WonderCam. Switch the function of the WonderCam&#39;s vision module to image classification. Set the connecting rod parameters for the robotic arm, and establish an initial posture for the arm using the inverse kinematics function.</p><p>​ (2) Next, create two variables named <strong>Count</strong> and <strong>Last Result</strong> to store the number of times and the ID recognized by the vision module. Initialize both variables with a value of 0, as depicted in the figure below:</p><img loading="lazy" height="464" width="847" src="'+Z+'" class="common_img" style="width:800px;"><ol start="2"><li><strong>Mask Identification</strong></li></ol><p>​ (1) Mask identification is primarily achieved through the image recognition function of WonderCam module. To facilitate continuous recognition and update of results, a repetitive loop statement is employed.</p><p>​ (2) In order to ensure accurate recognition, the program saves the recognized results and performs subsequent recognition. It then compares the current recognition result with the previous one. When there are five consecutive matches between the results, it is determined that the face has been successfully recognized, allowing the program to proceed to the next step of judgment.</p><p>​ (3) This iterative process guarantees reliability in identifying faces wearing masks, enabling seamless decision-making for subsequent actions.</p><img loading="lazy" height="398" width="834" src="'+Q+'" class="common_img" style="width:800px;"><ol start="3"><li><strong>Make Judgement and Provide Feedback</strong></li></ol><p>​ (1) Once the recognition count reaches 5, it will reset back to 0.</p><p>​ (2) If the WonderCam vision module fails to recognize a face for 5 consecutive times, the dot matrix display will showcase <img loading="lazy" height="24" width="40" src="'+e+'" class="inline-icon">.</p><img loading="lazy" height="202" width="436" src="'+W+'" class="common_img" style="width:800px;"><p>​ (3) When the WonderCam vision module successfully detects a face wearing a mask for 5 consecutive times, the dot matrix module will display <img loading="lazy" height="19" width="39" src="'+t+'" class="inline-icon">.</p><img loading="lazy" height="123" width="471" src="'+j+'" class="common_img" style="width:800px;"><p>​ (4) In the case where the module recognizes a face without a mask, the dot matrix display will demonstrate <img loading="lazy" height="21" width="41" src="'+o+'" class="inline-icon"> indicating face recognition without a mask. Additionally, the buzzer will emit three beeping sounds to alert the user.</p><img loading="lazy" height="198" width="644" src="'+D+'" class="common_img" style="width:800px;"><h3 id="_6-3-6-faq" tabindex="-1">6.3.6 FAQ <a class="header-anchor" href="#_6-3-6-faq" aria-label="Permalink to &quot;6.3.6 FAQ&quot;">​</a></h3><p><strong>Q1</strong>: Why is the dot matrix module not displaying properly after starting the game?</p><p><strong>A1</strong>: Please follow these steps to troubleshoot the issue:</p><p>Ensure that the wiring of the dot matrix module is correct, specifically connected to the correct interface (Interface No. 8).</p><p>Restart both the robot arm and the main controller. It is crucial to turn on the robot arm first and then power on the main controller.</p>',125)])])}const ie=n(N,[["render",G]]);export{oe as __pageData,ie as default};
